"""One shared player for locally backed-up calls, loaded only on request."""
from ui_layout import icon

def recording_player():
    return '<div id="recording-player" class="recording-player" role="region" aria-label="錄音播放器" hidden><div class="recording-player-top"><div class="player-context"><span class="player-eyebrow">錄音播放</span><strong id="recording-player-title"></strong></div><button type="button" id="recording-player-close" class="player-close" aria-label="關閉播放器">'+icon('close')+'</button></div><div class="recording-player-controls"><audio id="recording-audio" controls preload="none" aria-label="通話錄音"></audio><label class="player-speed">播放速度<select id="recording-speed"><option value="0.75">0.75×</option><option value="1" selected>1×</option><option value="1.25">1.25×</option><option value="1.5">1.5×</option><option value="2">2×</option></select></label></div><p id="recording-player-feedback" class="error" role="status" hidden></p></div>'+SCRIPT

SCRIPT='''<script>(()=>{const panel=document.getElementById('recording-player'),audio=document.getElementById('recording-audio'),title=document.getElementById('recording-player-title'),speed=document.getElementById('recording-speed'),feedback=document.getElementById('recording-player-feedback');let current=null,request=0;const play='<path d="m8 5 11 7-11 7Z"/>',pause='<path d="M8 5v14M16 5v14"/>';function reset(button){if(!button)return;button.setAttribute('aria-pressed','false');button.classList.remove('playing');button.querySelector('.play-label').textContent='播放';button.querySelector('svg').innerHTML=play}function sync(){const active=current&&!audio.paused&&!audio.ended;if(current){current.setAttribute('aria-pressed',String(!!active));current.classList.toggle('playing',!!active);current.querySelector('.play-label').textContent=active?'暫停':'播放';current.querySelector('svg').innerHTML=active?pause:play}}function fail(message){feedback.textContent=message;feedback.hidden=false;sync()}document.addEventListener('click',event=>{const button=event.target.closest('.recording-play');if(!button)return;const id=++request;feedback.hidden=true;if(current===button&&!audio.paused&&!audio.error){audio.pause();return}if(current!==button){audio.pause();reset(current);current=button;title.textContent=button.dataset.recordingLabel;audio.src=button.dataset.recordingSrc}else if(audio.error){audio.load()}panel.hidden=false;document.body.classList.add('has-recording-player');audio.playbackRate=Number(speed.value);const result=audio.play();if(result)result.catch(error=>{if(id===request&&error.name!=='AbortError')fail('無法播放此錄音，請重試或下載 WAV。')})});for(const event of ['play','pause','ended'])audio.addEventListener(event,sync);audio.addEventListener('loadedmetadata',()=>{audio.playbackRate=Number(speed.value)});audio.addEventListener('error',()=>{if(current){audio.pause();fail('音檔讀取失敗，可再次按播放重試，或下載 WAV。')}});speed.addEventListener('change',()=>{audio.playbackRate=Number(speed.value)});document.getElementById('recording-player-close').addEventListener('click',()=>{request++;audio.pause();reset(current);const previous=current;current=null;audio.removeAttribute('src');audio.load();panel.hidden=true;document.body.classList.remove('has-recording-player');if(previous)previous.focus()})})();</script>'''
